def prob(n):
    rand = random.randint(0,101)
    if rand < n:
        return True
    else:
        return False
def floodfill(a,x,y,n):
    white = [255,255,255]
    if(x = 300 or y = 300):
        return

    if(prob(n)):
        a[x,y] = white
    floodfill(a, x+1, y, n-1)
    floodfill(a, x-1, y, n-1)
    floodfill(a, x, y+1, n-1)
    floodfill(a, x, y-1, n-1)

