def xor(*operands, falsechoice = 0, truechoice = 0):
  """ falsechoice, truechoice: 1 returns first, 0 returns bool, -1 returns last """
  if not operands:
    raise TypeError('at least one operand expected')
  choices = [falsechoice, truechoice]
  results = {}
  x = False
  for o in operands:
    # evaluate each operand only once so at to avoid unintended side effects
    b = bool(o)
    x ^= b
    c = choices[b]
    if c &lt; 0 or (c &gt; 0 and b not in results):
      results[b] = o
  return results.get(x, x)

