    try:
        iter(x)
        return True
    except TypeError:
        return False


def flatten(x, reduce=iter):
    for i in x:
        if isiter(i):
            r = reduce((j for j in flatten(i, reduce=reduce))
            if isiter(r):
                yield from r
            else:
                yield r
        else:
            yield i

